-- HLBG1A: renumbered copy of DarkChaos spawns (map 1411 -> 20411, area 6738 -> 20411, zone 47 -> 20411).
-- GUID ranges (the core stops the server when a spawn id reaches 0xFFFFFF = 16777215, so they must stay below that):
--   creature      16000000 .. 16000155   (DarkChaos: 9001718 .. 9001873)
--   gameobject    16200000 .. 16200421   (DarkChaos: 5714939 .. 5715360)
--   waypoint_data 895000000 .. 895000009 (ids are not limited; DarkChaos: 53004947 .. 53004956; creature_addon.path_id follows)
-- Re-runnable: first removes EVERYTHING on map 20411 (the map belongs to this module only), including rows an earlier version of
-- this file put there with other guids. RUN 00_conflict_check_read_only.sql FIRST; undo with 99_remove_all.sql.
DELETE ca FROM `creature_addon` ca JOIN `creature` c ON c.`guid` = ca.`guid` WHERE c.`map` = 20411;
DELETE FROM `creature` WHERE `map` = 20411;
DELETE FROM `gameobject` WHERE `map` = 20411;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 895000000 AND 895000009;




